<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { state,stamp,uid,setOrderStatus } from '../lib/store'
import { requireRole,notify } from '../lib/actions'
import FileUpload from './FileUpload.vue'
const props=defineProps({order:Object,kind:String,link:Boolean})
const router=useRouter(),open=ref(false),reason=ref(''),hours=ref(24),stars=ref(5),tags=ref([]),files=ref([])
const labels={extend:'申请延期',review:'评价',dispute:'发起仲裁'}
function show(){if(!requireRole(router,props.kind==='review'?state.session.role:'creator'))return;if(props.kind==='extend'&&props.order.extended){ElMessage.info('每份订单仅可申请延期 1 次');return}open.value=true}
function submit(){const o=props.order;if(props.kind==='extend'){if(reason.value.trim().length<10){ElMessage.warning('请填写至少 10 字延期原因');return}if(o.extended)return;o.extended=true;o.extension={hours:hours.value,reason:reason.value,status:'待处理',at:stamp()};notify('演示延期申请已保存，可在商家工作台处理')}else if(props.kind==='review'){if(reason.value.trim().length<15){ElMessage.warning('评价内容须为 15–500 字');return}if(state.reviews.some(r=>r.orderId===o.id&&r.role===state.session.role)){ElMessage.info('此订单已评价');open.value=false;return}state.reviews.push({id:uid('R'),orderId:o.id,role:state.session.role,stars:stars.value,tags:tags.value,text:reason.value,at:stamp()});notify('演示评价已保存')}else{if(reason.value.trim().length<10){ElMessage.warning('请填写至少 10 字纠纷原因');return}state.disputes.push({id:uid('D'),taskId:o.taskId,orderId:o.id,reason:reason.value,files:files.value.map(f=>({name:f.name,size:f.size})),status:'处理中',at:stamp()});setOrderStatus(o,'纠纷中');notify('演示仲裁工单已创建，未提交真实平台')}open.value=false}
</script>
<template><el-button :link="link" :type="link?'primary':'default'" :disabled="kind==='extend'&&order.extended||kind==='review'&&state.reviews.some(r=>r.orderId===order.id&&r.role===state.session.role)" @click="show">{{kind==='extend'&&order.extended?'已申请延期':kind==='review'&&state.reviews.some(r=>r.orderId===order.id&&r.role===state.session.role)?'已评价':labels[kind]}}</el-button><el-dialog v-model="open" :title="labels[kind]" width="520px" :close-on-click-modal="false"><div class="app-ui dialog-stack"><p>{{order.title}}</p><template v-if="kind==='extend'"><p class="info-note">每单可申请 1 次，最多延期 48 小时；正式服务中商家 12 小时未处理视为同意。演示需在商家工作台手动处理。</p><el-input-number v-model="hours" :min="1" :max="48" :precision="0" aria-label="申请延期小时数"/></template><template v-if="kind==='review'"><el-rate v-model="stars" :allow-half="false"/><el-checkbox-group v-model="tags"><el-checkbox v-for="x in state.session.role==='merchant'?['出图快','还原度高','沟通顺畅','专业靠谱']:['需求清晰','付款爽快','沟通及时']" :key="x" :value="x">{{x}}</el-checkbox></el-checkbox-group></template><el-input v-model="reason" type="textarea" :rows="4" :maxlength="500" :minlength="kind==='review'?15:10" show-word-limit :placeholder="kind==='review'?'写下这次合作的真实感受，15–500 字':'请说明原因，至少 10 字'"/><FileUpload v-if="kind==='dispute'" v-model="files" :limit="5" :video="false" label="添加凭证"/></div><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" @click="submit">确认提交（演示）</el-button></template></el-dialog></template>
